"""Small, dependency-free content seals shared by the A/B gate harness."""

import hashlib
import json
import pathlib


def file_sha256(path):
    return hashlib.sha256(pathlib.Path(path).read_bytes()).hexdigest()


def tree_seal(root):
    """Content seal for a solver/checker tree, excluding generated bytecode."""
    root = pathlib.Path(root)
    out = {}
    for path in sorted(root.rglob("*")):
        if (not path.is_file() or "__pycache__" in path.parts
                or path.suffix == ".pyc"):
            continue
        out[str(path.relative_to(root))] = file_sha256(path)
    return out


def seal_id(seal):
    payload = json.dumps(seal, sort_keys=True, separators=(",", ":")).encode()
    return hashlib.sha256(payload).hexdigest()
